<?php require dirname(__DIR__,3).'/includes/bootstrap.php';$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$q=$pdo->prepare('SELECT id FROM users WHERE email=? AND status="active" AND deleted_at IS NULL');$q->execute([$email]);if($u=$q->fetch()){$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$u['id'],hash('sha256',$token)]);$pdo->prepare('INSERT INTO notifications(user_id,type,title,message) VALUES(?,"security","Password reset requested","A password reset was requested. Contact the administrator if this was not you.")')->execute([$u['id']]);}$sent=true;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account recovery</title><link rel="stylesheet" href="<?=app_url('assets/css/app.css')?>"></head><body class="auth-page"><main class="auth-card"><div class="auth-brand"><span class="brand-mark">HF</span><div><b>Account recovery</b><small>Secure administrator access</small></div></div><?php if($sent):?><span class="eyebrow">REQUEST RECEIVED</span><h1>Recovery request created</h1><p>If an active account matches, a secure reset request has been created. Contact your Super Administrator when email delivery is not configured.</p><a class="btn primary" href="<?=app_url('auth/manage-admin/login/')?>">Return to sign in</a><?php else:?><span class="eyebrow">SECURE RECOVERY</span><h1>Forgot password?</h1><p>Enter your account email. The same confirmation is shown whether or not an account exists.</p><form method="post" class="stack"><?=csrf_field()?><label>Email Address<input type="email" name="email" required></label><button class="btn primary">Request secure reset</button></form><?php endif;?></main></body></html>
